"use client";

/**
 * GameLogo — the single per-game brand mark used everywhere a game identity is
 * shown across Nxeon: the marketing /game-servers grid + per-game pricing rows,
 * the per-game SEO landing heroes (GameLandingPage), the PricingExplorer game
 * sub-tabs, and the customer deploy picker (GameDeploy). It replaces the old
 * generic 🎮 emoji / gradient placeholders with the real logo, and gracefully
 * falls back so a surface is never blank.
 *
 * ── Drop-in convention (PRIMARY, owner-supplied official logos) ──────────────
 * The owner drops official logos at:
 *     public/logos/games/<family>.svg   ← preferred
 *     public/logos/games/<family>.png   ← also accepted (raster)
 * where <family> is one of the six canonical GAME_FAMILIES (lib/games.ts):
 *     minecraft.svg  valheim.svg  rust.svg  palworld.svg  cs2.svg  terraria.svg
 * Drop a file at that path and it "just works": it takes precedence over the
 * bundled fallbacks below with NO code change (this component always probes the
 * drop-in path first).
 *
 * ── Resolution order (first that loads wins) ────────────────────────────────
 * SSR renders the first candidate; the browser falls through via <img onError>:
 *   1. /logos/games/<family>.svg        (owner drop-in — primary)
 *   2. /logos/games/<family>.png        (owner drop-in — raster)
 *   3. bundled known asset (see KNOWN_ASSET — ships in the repo today)
 *   4. the per-family emoji glyph on a subtle brand-gradient tile (never blank)
 *
 * The game's brand colour is always kept for a soft glow/ring behind the mark so
 * the tile still looks designed even before an official logo is dropped in, and
 * terraria (no bundled asset yet) simply shows its emoji until the owner adds
 * public/logos/games/terraria.svg.
 */

import { useState } from "react";

/** Per-family display name, emoji fallback glyph, and brand gradient stops. */
export const GAME_VISUAL: Record<
  string,
  { name: string; glyph: string; from: string; to: string }
> = {
  minecraft: { name: "Minecraft", glyph: "⛏️", from: "#3b6d1f", to: "#6aab3a" },
  valheim: { name: "Valheim", glyph: "🪓", from: "#284c6f", to: "#4a86b8" },
  rust: { name: "Rust", glyph: "🔧", from: "#8a3b1e", to: "#cd6a37" },
  palworld: { name: "Palworld", glyph: "🐾", from: "#0f6f69", to: "#25c0b4" },
  cs2: { name: "Counter-Strike 2", glyph: "🎯", from: "#8a5a12", to: "#e0a63a" },
  terraria: { name: "Terraria", glyph: "🌳", from: "#3a5a2a", to: "#7aa441" },
};

/** Neutral fallback for an unknown family id. */
const NEUTRAL = { name: "Game", glyph: "🎮", from: "#334155", to: "#64748b" };

/**
 * Best currently-bundled asset per family (fallback #3). These ship in the repo
 * today (public/games/*) and give a real logo on staging BEFORE the owner drops
 * official files into public/logos/games/. Terraria has no bundled asset, so it
 * falls through to the emoji glyph.
 */
const KNOWN_ASSET: Record<string, string> = {
  minecraft: "/games/minecraft.svg",
  cs2: "/games/cs2.svg",
  rust: "/games/rust.png",
  palworld: "/games/palworld.png",
  valheim: "/games/valheim.png",
};

export function GameLogo({
  family,
  size = 48,
  className = "",
}: {
  family: string;
  /** Tile edge length in px. Default 48. */
  size?: number;
  className?: string;
}) {
  const visual = GAME_VISUAL[family] ?? NEUTRAL;

  // Candidate srcs in resolution order. Owner drop-in first, bundled asset last.
  const candidates = [
    `/logos/games/${family}.svg`,
    `/logos/games/${family}.png`,
    KNOWN_ASSET[family],
  ].filter(Boolean) as string[];

  const [idx, setIdx] = useState(0);
  const exhausted = idx >= candidates.length;
  const src = candidates[idx];
  const pad = Math.max(4, Math.round(size * 0.16));

  return (
    <span
      className={`relative inline-flex shrink-0 items-center justify-center overflow-hidden rounded-xl border border-white/10 ${className}`}
      style={{
        width: size,
        height: size,
        // Emoji tile gets the full brand gradient; a real logo sits on a neutral
        // frosted tile — both carry a soft brand glow so it reads as designed.
        background: exhausted
          ? `linear-gradient(135deg, ${visual.from}, ${visual.to})`
          : "rgba(255,255,255,0.06)",
        boxShadow: `0 0 ${Math.round(size * 0.55)}px -${Math.round(size * 0.3)}px ${visual.to}`,
      }}
    >
      {exhausted ? (
        <span aria-hidden style={{ fontSize: Math.round(size * 0.5), lineHeight: 1 }}>
          {visual.glyph}
        </span>
      ) : (
        // eslint-disable-next-line @next/next/no-img-element -- onError fallback chain needs a plain <img>
        <img
          key={src}
          src={src}
          alt={`${visual.name} logo`}
          onError={() => setIdx((i) => i + 1)}
          style={{
            width: size - pad * 2,
            height: size - pad * 2,
            objectFit: "contain",
          }}
        />
      )}
    </span>
  );
}

